package java.util.concurrent;
import java.util.*;
public class CopyOnWriteArrayList<E> extends AbstractList<E> implements RandomAccess,Cloneable,java.io.Serializable {
 private ArrayList<E> data; public CopyOnWriteArrayList(){data=new ArrayList<E>();} public CopyOnWriteArrayList(Collection<? extends E> c){data=new ArrayList<E>(c);} public CopyOnWriteArrayList(E[] a){this();for(E e:a)data.add(e);} private ArrayList<E> copy(){return new ArrayList<E>(data);}
 public int size(){return data.size();} public E get(int i){return data.get(i);} public E set(int i,E e){ArrayList<E> n=copy();E old=n.set(i,e);data=n;return old;} public void add(int i,E e){ArrayList<E> n=copy();n.add(i,e);data=n;} public E remove(int i){ArrayList<E> n=copy();E old=n.remove(i);data=n;return old;} public boolean remove(Object value){ArrayList<E> n=copy(); boolean changed=n.remove(value); if(changed)data=n; return changed;} public void clear(){data=new ArrayList<E>();} public boolean addIfAbsent(E e){if(contains(e))return false;return add(e);} public int addAllAbsent(Collection<? extends E> c){int n=0;for(E e:c)if(addIfAbsent(e))n++;return n;} public int indexOf(E e,int index){for(int i=index;i<size();i++)if(Objects.equals(e,get(i)))return i;return -1;} public int lastIndexOf(E e,int index){for(int i=index;i>=0;i--)if(Objects.equals(e,get(i)))return i;return -1;}
 public Iterator<E> iterator(){return listIterator();} public ListIterator<E> listIterator(){return listIterator(0);} public ListIterator<E> listIterator(int i){final ListIterator<E> it=data.listIterator(i);return new ListIterator<E>(){public boolean hasNext(){return it.hasNext();}public E next(){return it.next();}public boolean hasPrevious(){return it.hasPrevious();}public E previous(){return it.previous();}public int nextIndex(){return it.nextIndex();}public int previousIndex(){return it.previousIndex();}public void remove(){throw new UnsupportedOperationException();}public void set(E e){throw new UnsupportedOperationException();}public void add(E e){throw new UnsupportedOperationException();}};}
 public Object clone(){return new CopyOnWriteArrayList<E>(data);}
}
